def build(root: pathlib.Path) -> None:
    rows = []
    for rid, desc, impl, acc in ROWS:
        prefix = rid.split("-")[0]
        spec, master = SPEC[prefix]
        ev = EVIDENCE.get(rid, {})
        rows.append({"id": rid, "description": desc, "source": {"phase6_spec": spec, "master_document": master}, "implementation": impl, "acceptance": acc,
                     "tests": ev.get("tests", []), "status": ev.get("status", "Missing"), "note": ev.get("note", "")})
    (root / "docs/phase6/requirements.json").write_text(json.dumps(rows, indent=1, ensure_ascii=False) + "\n", encoding="utf-8")
    counts: dict = {}
    for r in rows:
        counts[r["status"]] = counts.get(r["status"], 0) + 1
    lines = ["# Phase 6 requirements register", "",
             "Statuses: **Complete** = implemented and covered by named, passing automated tests (and a browser check where a person sees it). **Partial** = implemented with a stated gap. "
             "**Missing** = not implemented. **Blocked** = cannot be done in this environment. **Unverified** = code exists but the test that would prove it could not be run here.", "",
             "Generated by `docs/phase6/build_register.py`; checked by `backend/tests/test_phase6_register.py`. Totals: " + ", ".join(f"{k} {v}" for k, v in sorted(counts.items())) + ".", "",
             "| ID | Requirement | Source | Implementation | Acceptance | Tests | Status |", "|---|---|---|---|---|---|---|"]
    for r in rows:
        tests = "<br>".join(r["tests"]) if r["tests"] else "—"
        note = f" — {r['note']}" if r["note"] else ""
        lines.append(f"| {r['id']} | {r['description']} | {r['source']['phase6_spec']}; {r['source']['master_document']} | `{r['implementation']}` | {r['acceptance']} | {tests} | **{r['status']}**{note} |")
    (root / "docs/phase6/REQUIREMENTS_REGISTER.md").write_text("\n".join(lines) + "\n", encoding="utf-8")


if __name__ == "__main__":
    build(pathlib.Path(sys.argv[1]) if len(sys.argv) > 1 else pathlib.Path("."))
    print(f"{len(ROWS)} requirements")
